CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', alert_distance_m integer NOT NULL DEFAULT 500 CHECK (alert_distance_m BETWEEN 100 AND 5000));
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_transport_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES (NEW.id); RETURN NEW; END $$;
CREATE TRIGGER transport_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_transport_profile();
CREATE TABLE public.approved_personnel (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE, phone text UNIQUE, CHECK (email IS NOT NULL OR phone IS NOT NULL));
GRANT ALL ON public.approved_personnel TO service_role;
ALTER TABLE public.approved_personnel ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role text NOT NULL CHECK (role IN ('admin','user')), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.is_personnel() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.approved_personnel p JOIN auth.users u ON u.id = auth.uid() WHERE (p.email IS NOT NULL AND lower(p.email) = lower(u.email) AND u.email_confirmed_at IS NOT NULL) OR (p.phone IS NOT NULL AND p.phone = u.phone AND u.phone_confirmed_at IS NOT NULL)) $$;
REVOKE ALL ON FUNCTION public.is_personnel() FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.is_personnel() TO authenticated;
CREATE TABLE public.bus_routes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_number text NOT NULL UNIQUE, bus_number text NOT NULL UNIQUE, imei text NOT NULL UNIQUE CHECK (imei ~ '^[0-9]{15}$'), origin text, destination text, direction text, geometry jsonb, stops jsonb NOT NULL DEFAULT '[]', driver_name text, driver_phone text, default_color text NOT NULL DEFAULT '#658B80');
GRANT SELECT ON public.bus_routes TO authenticated; GRANT ALL ON public.bus_routes TO service_role;
ALTER TABLE public.bus_routes ENABLE ROW LEVEL SECURITY;
CREATE POLICY personnel_route_read ON public.bus_routes FOR SELECT TO authenticated USING (public.is_personnel());
CREATE TABLE public.bus_positions (route_id uuid PRIMARY KEY REFERENCES public.bus_routes(id) ON DELETE CASCADE, latitude double precision NOT NULL CHECK (latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK (longitude BETWEEN -180 AND 180), speed_mps double precision CHECK (speed_mps >= 0), heading double precision, recorded_at timestamptz NOT NULL, eta_seconds integer CHECK (eta_seconds >= 0), eta_target_latitude double precision, eta_target_longitude double precision);
GRANT SELECT ON public.bus_positions TO authenticated; GRANT ALL ON public.bus_positions TO service_role;
ALTER TABLE public.bus_positions ENABLE ROW LEVEL SECURITY;
CREATE POLICY personnel_position_read ON public.bus_positions FOR SELECT TO authenticated USING (public.is_personnel());
ALTER PUBLICATION supabase_realtime ADD TABLE public.bus_positions;
CREATE TABLE public.admin_credentials (id integer PRIMARY KEY CHECK (id = 1), salt text NOT NULL, verifier text NOT NULL, version integer NOT NULL DEFAULT 1);
GRANT ALL ON public.admin_credentials TO service_role; ALTER TABLE public.admin_credentials ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.admin_attempts (user_id uuid PRIMARY KEY, failures integer NOT NULL DEFAULT 0, window_start timestamptz NOT NULL DEFAULT now(), blocked_until timestamptz);
GRANT ALL ON public.admin_attempts TO service_role; ALTER TABLE public.admin_attempts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.admin_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, credential_version integer NOT NULL, expires_at timestamptz NOT NULL);
GRANT ALL ON public.admin_sessions TO service_role; ALTER TABLE public.admin_sessions ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.reserve_admin_attempt(p_user uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE a public.admin_attempts; BEGIN INSERT INTO public.admin_attempts(user_id) VALUES (p_user) ON CONFLICT DO NOTHING; SELECT * INTO a FROM public.admin_attempts WHERE user_id = p_user FOR UPDATE; IF a.blocked_until > now() THEN RETURN false; END IF; IF a.window_start < now() - interval '15 minutes' THEN a.failures := 0; a.window_start := now(); END IF; UPDATE public.admin_attempts SET failures = a.failures + 1, window_start = a.window_start, blocked_until = CASE WHEN a.failures + 1 >= 5 THEN now() + interval '15 minutes' ELSE NULL END WHERE user_id = p_user; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.reserve_admin_attempt(uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.reserve_admin_attempt(uuid) TO service_role;
CREATE TABLE public.voice_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), route_id uuid NOT NULL REFERENCES public.bus_routes(id), storage_path text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.voice_messages TO authenticated; GRANT ALL ON public.voice_messages TO service_role;
ALTER TABLE public.voice_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_message_read ON public.voice_messages FOR SELECT TO authenticated USING (user_id = auth.uid() AND public.is_personnel());
CREATE POLICY own_message_send ON public.voice_messages FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND public.is_personnel() AND storage_path LIKE auth.uid()::text || '/%');